components.css:
.task-card {
    position: relative;
    display:flex;
    flex-direction:column;
    min-height:0;
    padding:1.15rem 1.2rem;
    border:1px solid var(--color-border-strong);
    border-radius:var(--radius-md);
    background:var(--color-surface-elevated);
    transition: transform 220ms cubic-bezier(.22,1,.36,1), border-color 220ms ease;
    overflow:hidden;
  }

.task-card__chip {
    display:inline-flex;
    align-items:center;
    padding:.18rem .55rem;
    border-radius:var(--radius-xl);
    background:var(--color-theme-soft);
    color:var(--color-theme);
    font-size:.7rem;
    font-weight:800;
    letter-spacing:.02em;
    white-space:nowrap;
  }

.home-card {
    position: relative;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    gap: 0;
    min-height: 0;
    height: 100%;
    padding: 22px 4px;
    border: 0;
    border-bottom: 1px solid var(--color-border);
    border-radius: 0;
    background: transparent;
    color: inherit;
    text-decoration: none;
    transition:
      transform 220ms ease,
      color 220ms ease;
  }

.lang-label {
    position: absolute;
    bottom: 10px;
    font-size: var(--text-xs);
    font-weight: 900;
    padding: 2px 4px;
    border-radius: var(--radius-sm);
    line-height: 1;
    background: var(--color-theme);
    color: white;
  }

.wechat-follow-card {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 34px;
    text-align: center;
    background: var(--color-surface);
  }
